<?php $this->assign('title', 'Especialidades'); ?><div class="d-flex justify-content-between mb-4"><h1 class="h3">Especialidades</h1><?= $this->Html->link('Nova especialidade', ['action' => 'add'], ['class' => 'btn btn-primary']) ?></div><div class="card border-0 shadow-sm"><table class="table mb-0"><thead><tr><th>Nome</th><th>Descrição</th><th></th></tr></thead><tbody><?php foreach ($especialidades as $especialidade): ?><tr><td><?= h($especialidade->nome) ?></td><td><?= h($especialidade->descricao ?: '-') ?></td><td><?= $this->Html->link('Editar', ['action' => 'edit', $especialidade->id], ['class' => 'btn btn-sm btn-outline-primary']) ?></td></tr><?php endforeach; ?></tbody></table></div>
